// Package documents is the optional Documents module: PDF templates built
// from blocks in the dashboard (Documents menu), filled with the data of a
// record and formulas, generated by the flows ("Generate document" step) and
// the dashboard. The PDFs are drawn in Go (go-pdf/fpdf), offline.
//
// It is removable: run "pocketbaseplus documents uninstall --yes" (deletes
// the templates and the generated documents), then remove documents.Register
// from main.go and this folder.
package documents

import (
	"crypto/rand"
	"embed"
	"encoding/hex"
	"fmt"
	"io/fs"
	"net/http"
	"strings"
	"sync"
	"time"

	"github.com/pocketbase/dbx"
	validation "github.com/pocketbase/ozzo-validation/v4"
	"github.com/pocketbase/pocketbase"
	"github.com/pocketbase/pocketbase/apis"
	"github.com/pocketbase/pocketbase/core"
	"github.com/spf13/cobra"

	"github.com/Namarusa/PocketbasePlus/internal/flows"
	"github.com/Namarusa/PocketbasePlus/internal/formula"
	"github.com/Namarusa/PocketbasePlus/internal/internalcols"
	"github.com/Namarusa/PocketbasePlus/internal/mail"
	"github.com/Namarusa/PocketbasePlus/internal/pdfview"
)

const (
	TemplatesCollection = "document_templates"
	DocumentsCollection = "documents"
	// ExtName is the dashboard extension of the module (/_/extensions/{ExtName}/).
	ExtName = "pocketbaseplus-documents"

	previewTTL   = 5 * time.Minute
	maxPreviews  = 50
	maxSpecBytes = 1 << 20
)

//go:embed all:ext
var extFS embed.FS

// Register adds the module: hooks, routes, the dashboard pages and the
// "documents uninstall" command.
func Register(app *pocketbase.PocketBase) {
	app.RootCmd.AddCommand(command(app))
	Bind(app)
}

// Bind adds the hooks and routes of the module.
func Bind(app core.App) {
	internalcols.Add(TemplatesCollection, DocumentsCollection)
	flows.SetDocuments(&flows.Documents{
		Generate: func(r flows.DocumentRequest) (map[string]any, error) {
			doc, err := Generate(r.Ctx, r.App, r.Template, r.Record, r.Values, r.Source)
			if err != nil {
				return nil, err
			}
			return Output(doc), nil
		},
		File:  File,
		Bytes: Bytes,
		Exists: func(app core.App, id string) bool {
			_, err := app.FindRecordById(TemplatesCollection, id)
			return err == nil
		},
	})
	mail.SetAttachmentLoader(Bytes)

	files, err := fs.Sub(extFS, "ext")
	if err != nil {
		panic(err)
	}

	app.OnRecordValidate(TemplatesCollection).BindFunc(func(e *core.RecordEvent) error {
		if err := validateTemplate(e.App, e.Record); err != nil {
			return err
		}
		return e.Next()
	})
	// a template used by a flow can't be deleted (the flow would fail)
	app.OnRecordDelete(TemplatesCollection).BindFunc(func(e *core.RecordEvent) error {
		var names []string
		_ = e.App.DB().Select("name").From("flows").Where(dbx.NewExp("steps LIKE {:id}", dbx.Params{"id": "%" + e.Record.Id + "%"})).Column(&names)
		if len(names) > 0 {
			return apis.NewBadRequestError(fmt.Sprintf("The template is used by the flows: %s. Change their Generate document steps first.", strings.Join(names, ", ")), nil)
		}
		return e.Next()
	})

	app.OnServe().BindFunc(func(se *core.ServeEvent) error {
		se.UIExtensions = append(se.UIExtensions, core.UIExtension{Name: ExtName, FS: files})
		se.Router.BindFunc(func(e *core.RequestEvent) error {
			if strings.HasPrefix(e.Request.URL.Path, "/_/extensions/"+ExtName+"/") {
				e.Response.Header().Set("Cache-Control", "no-cache") // revalidated after upgrades
			}
			return e.Next()
		})
		g := se.Router.Group("/api/documents")
		// the preview PDF is read by the iframe of the editor: its random
		// address is the access (an iframe can't send the token)
		g.GET("/preview/{token}", previewFile)
		// the PDF viewers: PDF.js, and the documents shown in the pages (signed links)
		g.GET("/pdfjs/{version}/{path...}", func(e *core.RequestEvent) error {
			return pdfview.Serve(e, e.Request.PathValue("version"), e.Request.PathValue("path"))
		})
		g.GET("/view/{template}/{target}", viewRoute)
		su := g.Group("")
		su.Bind(apis.RequireSuperuserAuth())
		su.POST("/preview", previewRoute)
		su.POST("/{id}/generate", generateRoute)
		su.GET("/templates", templatesRoute)
		su.GET("/starters", func(e *core.RequestEvent) error { return e.JSON(http.StatusOK, starters()) })
		return se.Next()
	})
}

// --- validation -------------------------------------------------------------------------------

func validateTemplate(app core.App, rec *core.Record) error {
	errs := validation.Errors{}
	for _, f := range []string{"header", "body", "footer", "lists", "margins"} {
		if len(rec.GetString(f)) > maxSpecBytes {
			errs[f] = validation.NewError("too_large", "The template is too large.")
		}
	}
	rec.Set("folder", strings.Join(strings.Fields(rec.GetString("folder")), " "))
	spec, err := specOf(rec)
	if err != nil {
		errs["body"] = validation.NewError("invalid_blocks", err.Error())
		return errs
	}
	if f := rec.GetString("format"); f != "custom" {
		if _, ok := formats[f]; !ok {
			errs["format"] = validation.NewError("invalid_format", "Choose a page format.")
		}
	} else if w, h := rec.GetFloat("width_mm"), rec.GetFloat("height_mm"); w < 50 || h < 50 || w > 1200 || h > 1200 {
		errs["width_mm"] = validation.NewError("invalid_size", "A custom page is 50 to 1200 mm wide and high.")
	}
	if col := rec.GetString("collection"); col != "" {
		c, err := app.FindCachedCollectionByNameOrId(col)
		if err != nil {
			errs["collection"] = validation.NewError("invalid_collection", "Unknown collection.")
		} else {
			rec.Set("collection", c.Name)
		}
	}
	if msg := checkSpec(app, spec); msg != "" {
		errs["body"] = validation.NewError("invalid_blocks", msg)
	} else {
		// the ids given to the new blocks
		rec.Set("header", spec.Header)
		rec.Set("body", spec.Body)
		rec.Set("footer", spec.Footer)
	}
	if len(errs) > 0 {
		return errs
	}
	return nil
}

// checkSpec checks the blocks (types, formulas) and the lists; it returns
// the first problem.
func checkSpec(app core.App, spec *Spec) string {
	msg := ""
	ids := map[string]bool{}
	count := 0
	for _, part := range [][]Block{spec.Header, spec.Body, spec.Footer} {
		walk(part, func(b *Block) {
			count++
			if msg != "" {
				return
			}
			if !blockTypes[b.Type] {
				msg = fmt.Sprintf("unknown block type %q", b.Type)
				return
			}
			if b.ID == "" || ids[b.ID] {
				b.ID = randomID()
			}
			ids[b.ID] = true
			for _, src := range b.formulas() {
				if strings.Contains(src, "{{") {
					if _, err := formula.Parse(src, roots...); err != nil {
						msg = fmt.Sprintf("%s: %s", b.label(), err)
						return
					}
				}
			}
			if b.Type == "columns" && (len(b.Columns) < 1 || len(b.Columns) > 4) {
				msg = "columns: 1 to 4 columns"
			}
		})
	}
	if count > 500 {
		return "too many blocks (500 at most)"
	}
	if msg != "" {
		return msg
	}
	if strings.Contains(spec.Filename, "{{") {
		if _, err := formula.Parse(spec.Filename, roots...); err != nil {
			return "file name: " + err.Error()
		}
	}
	names := map[string]bool{}
	for _, l := range spec.Lists {
		if !listNameRegex.MatchString(l.Name) || names[l.Name] {
			return fmt.Sprintf("list %q: a unique name of letters, digits and _", l.Name)
		}
		names[l.Name] = true
		col, err := app.FindCachedCollectionByNameOrId(l.Collection)
		if err != nil {
			return fmt.Sprintf("list %s: unknown collection %q", l.Name, l.Collection)
		}
		probe := listPlaceholder.ReplaceAllString(l.Filter, "''")
		if _, err := app.FindRecordsByFilter(col, probe, l.Sort, 1, 0); err != nil {
			return fmt.Sprintf("list %s: %s", l.Name, err)
		}
	}
	return ""
}

func randomID() string {
	b := make([]byte, 6)
	_, _ = rand.Read(b)
	return hex.EncodeToString(b)
}

// --- routes -----------------------------------------------------------------------------------

type previewBody struct {
	ID       string         `json:"id"` // the saved template (its images)
	Name     string         `json:"name"`
	Spec     Spec           `json:"spec"`
	Record   string         `json:"record"` // collection
	RecordID string         `json:"recordId"`
	Values   map[string]any `json:"values"`
}

var previews = struct {
	sync.Mutex
	items map[string]previewItem
}{items: map[string]previewItem{}}

type previewItem struct {
	pdf      []byte
	filename string
	expires  time.Time
}

func previewRoute(e *core.RequestEvent) error {
	var body previewBody
	if err := e.BindBody(&body); err != nil {
		return e.BadRequestError("Invalid request body.", err)
	}
	spec := body.Spec
	spec.normalize()
	if msg := checkSpec(e.App, &spec); msg != "" {
		return e.JSON(http.StatusOK, map[string]any{"error": msg})
	}
	var tpl *core.Record
	if body.ID != "" {
		tpl, _ = e.App.FindRecordById(TemplatesCollection, body.ID)
	}
	var rec *core.Record
	if body.Record != "" {
		col, err := e.App.FindCachedCollectionByNameOrId(body.Record)
		if err != nil {
			return e.JSON(http.StatusOK, map[string]any{"error": "Unknown collection " + body.Record})
		}
		if body.RecordID != "" {
			rec, _ = e.App.FindRecordById(col, body.RecordID)
		}
		if rec == nil {
			rec, _ = e.App.FindFirstRecordByFilter(col, "")
		}
	}
	res, err := Make(e.Request.Context(), e.App, Input{Template: tpl, Spec: &spec, Name: body.Name, Record: rec, Values: body.Values, Compress: true})
	if err != nil {
		return e.JSON(http.StatusOK, map[string]any{"error": err.Error()})
	}
	token := randomID() + randomID() + randomID()
	previews.Lock()
	now := time.Now()
	for k, p := range previews.items {
		if now.After(p.expires) {
			delete(previews.items, k)
		}
	}
	if len(previews.items) >= maxPreviews {
		for k := range previews.items {
			delete(previews.items, k)
			break
		}
	}
	previews.items[token] = previewItem{pdf: res.PDF, filename: res.Filename, expires: now.Add(previewTTL)}
	previews.Unlock()
	out := map[string]any{"url": "/api/documents/preview/" + token, "pages": res.Pages, "filename": res.Filename, "errors": res.Errors, "size": len(res.PDF), "boxes": res.Boxes, "pageWidth": res.PageW, "pageHeight": res.PageH}
	if rec != nil {
		out["recordId"] = rec.Id
	}
	return e.JSON(http.StatusOK, out)
}

func previewFile(e *core.RequestEvent) error {
	previews.Lock()
	p, ok := previews.items[e.Request.PathValue("token")]
	previews.Unlock()
	if !ok || time.Now().After(p.expires) {
		return e.NotFoundError("The preview expired.", nil)
	}
	h := e.Response.Header()
	h.Set("Content-Type", "application/pdf")
	h.Set("Content-Disposition", `inline; filename="`+p.filename+`"`)
	h.Set("Cache-Control", "no-store")
	h.Set("X-Content-Type-Options", "nosniff")
	// shown in the editor's frame only
	h.Set("Content-Security-Policy", "frame-ancestors 'self'")
	h.Set("X-Frame-Options", "SAMEORIGIN")
	return e.Blob(http.StatusOK, "application/pdf", p.pdf)
}

func generateRoute(e *core.RequestEvent) error {
	var body struct {
		RecordID string         `json:"recordId"`
		Values   map[string]any `json:"values"`
	}
	if err := e.BindBody(&body); err != nil {
		return e.BadRequestError("Invalid request body.", err)
	}
	doc, err := Generate(e.Request.Context(), e.App, e.Request.PathValue("id"), body.RecordID, body.Values, "dashboard")
	if err != nil {
		return e.BadRequestError(err.Error(), nil)
	}
	return e.JSON(http.StatusOK, doc)
}

// templatesRoute lists the templates for the flow editor.
func templatesRoute(e *core.RequestEvent) error {
	list, err := e.App.FindRecordsByFilter(TemplatesCollection, "", "folder,name", 0, 0)
	if err != nil {
		return err
	}
	out := []map[string]any{}
	for _, t := range list {
		out = append(out, map[string]any{"id": t.Id, "name": t.GetString("name"), "slug": t.GetString("slug"), "folder": t.GetString("folder"), "collection": t.GetString("collection")})
	}
	return e.JSON(http.StatusOK, out)
}

// --- uninstall --------------------------------------------------------------------------------

func command(app *pocketbase.PocketBase) *cobra.Command {
	cmd := &cobra.Command{Use: "documents", Short: "Documents module (PDF templates)"}
	var yes bool
	uninstall := &cobra.Command{
		Use:          "uninstall",
		SilenceUsage: true,
		Short:        "Deletes the document templates and the generated documents (before removing the module from main.go)",
		RunE: func(cmd *cobra.Command, args []string) error {
			if _, err := app.FindCollectionByNameOrId(TemplatesCollection); err != nil {
				fmt.Println("The documents collections don't exist: nothing to uninstall.")
				return nil
			}
			templates, _ := app.CountRecords(TemplatesCollection)
			docs, _ := app.CountRecords(DocumentsCollection)
			if !yes {
				fmt.Printf("This deletes %d document templates and %d generated documents (flows using them will fail).\n"+
					"Back up pb_data first, then run again with --yes.\n", templates, docs)
				return nil
			}
			err := app.RunInTransaction(func(tx core.App) error {
				if err := dropCollections(tx); err != nil {
					return err
				}
				_, err := tx.DB().Delete("_migrations", dbx.HashExp{"file": migrationFile}).Execute()
				return err
			})
			if err != nil {
				return err
			}
			fmt.Printf("Deleted %d templates and %d documents. Now remove documents.Register(app) from main.go and the internal/documents folder.\n", templates, docs)
			return nil
		},
	}
	uninstall.Flags().BoolVar(&yes, "yes", false, "confirm the deletion")
	cmd.AddCommand(uninstall)
	return cmd
}
